// Combine all into a unified, verified catalog
export const ALL_LANGUAGES = [
  ...INDIAN_CONSTITUTIONAL_LANGUAGES,
  ...REGIONAL_INDIAN_LANGUAGES,
  ...GLOBAL_LANGUAGES_DATA,
  ...EXTENDED_VERIFIED_LANGUAGES
];

// Deduplicate by code
const uniqueMap = new Map();
ALL_LANGUAGES.forEach(lang => {
  if (!uniqueMap.has(lang.code)) {
    uniqueMap.set(lang.code, lang);
  }
});

export const VERIFIED_LANGUAGES_CATALOG = Array.from(uniqueMap.values());

// Helper methods
export function getLanguageByCode(code) {
  if (!code) return null;
  const normalized = code.toLowerCase().split('-')[0];
  return VERIFIED_LANGUAGES_CATALOG.find(l => l.code === normalized || l.iso3 === normalized) || null;
}

export function searchLanguages(query) {
  if (!query) return VERIFIED_LANGUAGES_CATALOG;
  const q = query.toLowerCase().trim();
  return VERIFIED_LANGUAGES_CATALOG.filter(l => 
    l.name.toLowerCase().includes(q) ||
    l.native.toLowerCase().includes(q) ||
    l.code.toLowerCase().includes(q) ||
    (l.region && l.region.toLowerCase().includes(q)) ||
    (l.family && l.family.toLowerCase().includes(q))
  );
}

export function checkBrowserVoiceSupport(langCode) {
  if (typeof window === 'undefined' || !window.speechSynthesis) {
    return { available: false, voiceName: null, exactMatch: false };
  }
  const voices = window.speechSynthesis.getVoices();
  const normalized = langCode.toLowerCase();
  
  const exact = voices.find(v => v.lang.toLowerCase() === normalized || v.lang.toLowerCase().startsWith(normalized + '-'));
  if (exact) {
    return { available: true, voiceName: exact.name, exactMatch: true, langTag: exact.lang };
  }
  return { available: false, voiceName: null, exactMatch: false };
}
